// CreateTable creates the G_L_Entry table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *GLEntry) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the G_L_Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *GLEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, GLEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetGLEntryPostgresTableSchema()
	} else {
		schema = GetGLEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create G_L_Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *GLEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, GLEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$G_L_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gl_account_no, posting_date)`,
		fmt.Sprintf("%s$G_L_Entry$gl_account_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gl_account_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gl_account_no, business_unit_code, department_code, project_code, posting_date)`,
		fmt.Sprintf("%s$G_L_Entry$gl_account_dimensions", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gl_account_dimensions: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$G_L_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (transaction_no)`,
		fmt.Sprintf("%s$G_L_Entry$transaction", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index transaction: %w", err)
	}
	var keys []sift.Key
	for _, spec := range gLEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, GLEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, GLEntryTableName, keys)
}

// gLEntrySIFTSpecs are the table's keys with sum_index_fields
func gLEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "gl_account_date",
			Fields: []sift.Column{{Name: "gl_account_no", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}, {Name: "debit_amount", Kind: sift.KindDecimal}, {Name: "credit_amount", Kind: sift.KindDecimal}, {Name: "additional_currency_amount", Kind: sift.KindDecimal}, {Name: "add_currency_debit_amount", Kind: sift.KindDecimal}, {Name: "add_currency_credit_amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "gl_account_dimensions",
			Fields: []sift.Column{{Name: "gl_account_no", Kind: sift.KindText}, {Name: "business_unit_code", Kind: sift.KindText}, {Name: "department_code", Kind: sift.KindText}, {Name: "project_code", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}, {Name: "debit_amount", Kind: sift.KindDecimal}, {Name: "credit_amount", Kind: sift.KindDecimal}, {Name: "additional_currency_amount", Kind: sift.KindDecimal}, {Name: "add_currency_debit_amount", Kind: sift.KindDecimal}, {Name: "add_currency_credit_amount", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *GLEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, GLEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range gLEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, GLEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: GLEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, GLEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

